// Centralized Front Controller Dispatcher with Interceptor Pipeline
export interface HttpRequest {
  path: string;
  method: string;
  headers: Record<string, string>;
  body: unknown;
}

export interface HttpResponse {
  statusCode: number;
  headers: Record<string, string>;
  body: unknown;
}

export type Interceptor = (req: HttpRequest) => Promise<HttpRequest | HttpResponse>;
export type CommandHandler = (req: HttpRequest) => Promise<HttpResponse>;

export class FrontController {
  private readonly interceptors: Interceptor[] = [];
  private readonly routes = new Map<string, CommandHandler>();

  use(interceptor: Interceptor): this {
    this.interceptors.push(interceptor);
    return this;
  }

  register(routeKey: string, handler: CommandHandler): this {
    this.routes.set(routeKey, handler);
    return this;
  }

  async handle(req: HttpRequest): Promise<HttpResponse> {
    // 1. Execute cross-cutting interceptor pipeline
    for (const interceptor of this.interceptors) {
      const result = await interceptor(req);
      if ("statusCode" in result) {
        return result; // Short-circuit (e.g., 401 Unauthorized or 429 Rate Limited)
      }
      req = result;
    }

    // 2. Dispatch to resolved command handler
    const routeKey = `${req.method.toUpperCase()} ${req.path}`;
    const handler = this.routes.get(routeKey);

    if (!handler) {
      return { statusCode: 404, headers: {}, body: { error: "Route not found" } };
    }

    try {
      return await handler(req);
    } catch (err: any) {
      return {
        statusCode: 500,
        headers: {},
        body: { error: "Internal Server Error", message: err.message },
      };
    }
  }
}

// Application Controller orchestrating multi-step wizard state machine
export type CheckoutStep = "CART" | "SHIPPING" | "CUSTOMS" | "PAYMENT" | "VERIFY_3DS" | "CONFIRMATION";

export interface CheckoutContext {
  cartId: string;
  isInternational: boolean;
  requiresFraudReview: boolean;
  requires3DSecure: boolean;
  step: CheckoutStep;
}

export class CheckoutApplicationController {
  getNextStep(context: CheckoutContext, action: "NEXT" | "BACK"): { step: CheckoutStep; view: string } {
    switch (context.step) {
      case "CART":
        return { step: "SHIPPING", view: "views/shipping-address.html" };

      case "SHIPPING":
        if (context.isInternational) {
          return { step: "CUSTOMS", view: "views/customs-declaration.html" };
        }
        return { step: "PAYMENT", view: "views/payment-methods.html" };

      case "CUSTOMS":
        return { step: "PAYMENT", view: "views/payment-methods.html" };

      case "PAYMENT":
        if (context.requires3DSecure) {
          return { step: "VERIFY_3DS", view: "views/biometric-challenge.html" };
        }
        return { step: "CONFIRMATION", view: "views/order-success.html" };

      case "VERIFY_3DS":
        return { step: "CONFIRMATION", view: "views/order-success.html" };

      case "CONFIRMATION":
        return { step: "CONFIRMATION", view: "views/order-success.html" };
    }
  }
}

