// Strict DTO definitions and bidirectional Assembler
export interface OrderItemDTO {
  sku: string;
  title: string;
  quantity: number;
  unitPriceCents: number;
  lineTotalCents: number;
}

export interface OrderDetailDTO {
  orderId: string;
  customerName: string;
  customerEmail: string;
  items: OrderItemDTO[];
  subtotalCents: number;
  taxCents: number;
  totalCents: number;
  isShipped: boolean;
}

export class OrderDTOAssembler {
  // Translates a rich, encapsulated domain entity into an immutable public wire contract
  static toDTO(order: any, customer: any): OrderDetailDTO {
    return {
      orderId: order.id,
      customerName: `${customer.firstName} ${customer.lastName}`,
      customerEmail: customer.email,
      items: order.getItems().map((item: any) => ({
        sku: item.sku,
        title: item.title,
        quantity: item.quantity,
        unitPriceCents: item.price.toCents(),
        lineTotalCents: item.calculateLineTotal().toCents(),
      })),
      subtotalCents: order.calculateSubtotal().toCents(),
      taxCents: order.calculateTax().toCents(),
      totalCents: order.calculateGrandTotal().toCents(),
      isShipped: order.status === "SHIPPED",
    };
  }
}

// Production Omnichannel Checkout Orchestrator
import { z } from "zod";

// 1. Inward Wire Contract (DTO with runtime schema validation)
export const CheckoutRequestSchema = z.object({
  customerId: z.string().uuid(),
  cartId: z.string().uuid(),
  channel: z.enum(["WEB", "MOBILE_IOS", "MOBILE_ANDROID", "POS_TERMINAL"]),
  shippingAddress: z.object({
    street: z.string().min(5),
    city: z.string(),
    countryCode: z.string().length(2),
    postalCode: z.string(),
  }),
  paymentMethod: z.object({
    token: z.string(),
    provider: z.enum(["STRIPE", "ADYEN", "APPLE_PAY"]),
  }),
});

export type CheckoutRequestDTO = z.infer<typeof CheckoutRequestSchema>;

export interface CheckoutResultDTO {
  success: boolean;
  orderId?: string;
  transactionReference?: string;
  error?: string;
}

// 2. Coarse-Grained Remote Facade (API Gateway Service Boundary)
export class CheckoutRemoteFacade {
  constructor(
    private readonly appController: CheckoutApplicationController,
    private readonly auditLogger: any,
  ) {}

  async processCheckout(rawPayload: unknown): Promise<CheckoutResultDTO> {
    // A. Boundary Validation: Fail fast before touching domain logic
    const parseResult = CheckoutRequestSchema.safeParse(rawPayload);
    if (!parseResult.success) {
      return {
        success: false,
        error: `Invalid checkout request: ${parseResult.error.issues.map(i => i.message).join(", ")}`,
      };
    }

    const dto = parseResult.data;

    // B. Execute coordinated workflow across domain boundaries
    try {
      const order = await this.appController.executeCheckoutWorkflow(dto);
      return {
        success: true,
        orderId: order.id,
        transactionReference: order.paymentReference,
      };
    } catch (err: any) {
      return {
        success: false,
        error: err.message || "Checkout failed due to domain rule violation",
      };
    }
  }
}

// 3. Application Controller: Orchestrating the Multi-Step Checkout Workflow
export class CheckoutApplicationController {
  constructor(
    private readonly cartRepository: any,
    private readonly inventoryService: any,
    private readonly taxCalculator: any,
    private readonly paymentGateway: any,
    private readonly orderRepository: any,
  ) {}

  async executeCheckoutWorkflow(dto: CheckoutRequestDTO): Promise<any> {
    // Step 1: Verify Cart & Hydrate In-Memory Aggregate
    const cart = await this.cartRepository.findById(dto.cartId);
    if (!cart || cart.isEmpty()) {
      throw new Error("Cannot checkout an empty or non-existent cart");
    }

    // Step 2: Atomic Inventory Reservation (Local Memory / Low-Latency Call)
    const reservation = await this.inventoryService.reserveItems(cart.getItems());
    if (!reservation.isSuccessful) {
      throw new Error("One or more items are out of stock");
    }

    // Step 3: Compute Taxes & Shipping based on Territory
    const shippingCost = dto.shippingAddress.countryCode === "US" ? 500 : 2500;
    const taxAmount = await this.taxCalculator.calculate(cart.getSubtotal(), dto.shippingAddress);
    const grandTotal = cart.getSubtotal() + shippingCost + taxAmount;

    // Step 4: Authorize & Capture Payment via External Gateway
    const paymentResult = await this.paymentGateway.charge({
      amountCents: grandTotal,
      token: dto.paymentMethod.token,
      provider: dto.paymentMethod.provider,
    });

    if (!paymentResult.isApproved) {
      await this.inventoryService.releaseReservation(reservation.id);
      throw new Error(`Payment declined: ${paymentResult.declineReason}`);
    }

    // Step 5: Finalize Order Entity & Commit
    const order = {
      id: "ord_" + Math.random().toString(36).slice(2, 9),
      customerId: dto.customerId,
      totalCents: grandTotal,
      paymentReference: paymentResult.transactionId,
      status: "COMPLETED",
    };

    await this.orderRepository.save(order);
    await this.cartRepository.clear(dto.cartId);

    return order;
  }
}
